#!/usr/bin/env node
/**
 * SV 脚本 API 文档同步工具（2026-09-13 新增）
 *
 * 需求（用户口述）：记录当前版本号；**正式部署后启动时**若用户宿主版本号"向前更新"，
 *   就去 https://resource.dreamtonics.com/scripting/index.html 取页脚的 **JSDoc 生成时间戳**，
 *   判断文档是否更新 ⇒ 更新本地 API 文档（skills/sv-scripting/api/*.md）并记录最新版本；
 *   下次再变再查。
 *
 * 判据：**页脚时间戳**（`Documentation generated by JSDoc x.y.z on <DATE>`）是权威信号 ——
 *   比"类数量/内容 diff"稳定得多；时间戳没变 ⇒ 文档没重生成 ⇒ 不必抓页面。
 *
 * 用法：
 *   node tools/api-docs-sync.cjs --check              # 抓页脚、与基线比对（默认动作）
 *   node tools/api-docs-sync.cjs --update             # 文档变了就重新抓全部类页面并重写本地 md
 *   node tools/api-docs-sync.cjs --update --force     # 时间戳没变也强制重写
 *   node tools/api-docs-sync.cjs --record-host 2.2.1  # 记录某宿主版本（或 --record-host auto 读桥心跳）
 *   node tools/api-docs-sync.cjs --startup            # 启动钩子：**离线**比对宿主版本，只提示、不出网
 *
 * ⚠️ 2026-09-14 分发政策（用户定案）：**更新 = 重新分发安装包**；客户端**不出网、不自动检测**。
 *   ⇒ `--startup` 只做离线比对 + 本地提示；`--check` / `--update` 是**开发侧手动**动作。
 */
const fs = require('fs');
const path = require('path');

const ROOT = path.join(__dirname, '..');
const API_DIR = path.join(ROOT, 'skills', 'sv-scripting', 'api');
const STATE = path.join(API_DIR, '_sync.json');
const BASE = 'https://resource.dreamtonics.com/scripting/';
const INDEX = BASE + 'index.html';
// 宿主版本基线的**读**（host-version-notice.cjs）与**写**（本文件 --record-host）共用一份解析
const HV = require('./lib-host-version.cjs');

const argv = process.argv.slice(2);
const FLAG = (n) => argv.includes(n);
const OPT = (n) => { const i = argv.indexOf(n); return i >= 0 ? argv[i + 1] : null; };

function loadState() {
  if (!fs.existsSync(STATE)) return null;
  try { return JSON.parse(fs.readFileSync(STATE, 'utf8')); } catch { return null; }
}
function saveState(s) { fs.writeFileSync(STATE, JSON.stringify(s, null, 1) + '\n', 'utf8'); }

async function http(url) {
  const res = await fetch(url, { redirect: 'follow' });
  if (!res.ok) throw new Error(url + ' → HTTP ' + res.status);
  return await res.text();
}

/** 站点上的类 = index 链接 ∪ （本地有、且在站点上仍返回 200 的）
 *  ⚠️ 实测：有 3 个类（ArrangementSelectionState / ScriptableNestedObject / TrackInnerSelectionState）
 *  在 index 页**没有链接**，但站点上确实存在 ⇒ 单纯用 index 链接当清单会"误判本地独有"、更新时还会漏掉它们。 */
async function fetchDocMeta() {
  const html = await http(INDEX);
  const foot = html.match(/Documentation generated by[\s\S]*?theme\./);
  const gen = html.match(/JSDoc\s+([\d.]+)<\/a>\s+on\s+([A-Za-z]{3}\s+[A-Za-z]{3}\s+\d{2}\s+\d{4}\s+\d{2}:\d{2}:\d{2}\s+(?:GMT[+-]\d{4}|[\w\s]+?))\s*(?:\(|using)/);
  const linked = [...new Set([...html.matchAll(/href="([A-Za-z_][A-Za-z0-9_]*)\.html"/g)].map((m) => m[1]))]
    .filter((n) => n !== 'index' && !NON_CLASS_NAMES.has(n)).sort();
  const extra = [];
  for (const c of localClasses()) {
    if (linked.includes(c)) continue;
    try { const res = await fetch(BASE + c + '.html', { method: 'GET' }); if (res.ok) extra.push(c); } catch { /* 离线或 404 ⇒ 忽略 */ }
  }
  return {
    generator: gen ? 'JSDoc ' + gen[1] : '?',
    generatedAt: gen ? gen[2].replace(/\s+/g, ' ').trim() : '?',
    footer: foot ? foot[0].replace(/<[^>]+>/g, '').replace(/\s+/g, ' ').trim() : '?',
    linkedClasses: linked,
    extraClasses: extra,
    classes: [...new Set(linked.concat(extra))].sort(),
  };
}

const localClasses = () => fs.readdirSync(API_DIR).filter((f) => f.endsWith('.md') && f !== 'README.md' && !NON_CLASS.has(f))
  .map((f) => f.replace(/\.md$/, '')).sort()

/**
 * **非类页面**（2026-09-19 新增）：`Home.md`（手册首页）与 `Tutorials.md`（5 篇教程）。
 * 它们由**本地官方手册存档**导入（`Downloads\sv script\`），**不由 `--update` 从站点抓** ——
 * 站点上首页是 `index.html`、教程是 `tutorial-*.html`，URL 形态与类页转换口径都不同。
 * 列在这里是为了：① 不被当成"本地多出来的类"报漂移；② 也不去站点上找同名类页。
 */
const NON_CLASS = new Set(['Home.md', 'Tutorials.md'])
const NON_CLASS_NAMES = new Set(['Home']);

function diffClasses(local, remote) {
  return { onlyLocal: local.filter((c) => !remote.includes(c)), onlyRemote: remote.filter((c) => !local.includes(c)) };
}

async function doCheck() {
  const st = loadState();
  console.log('基线（skills/sv-scripting/api/_sync.json）：');
  if (!st) console.log('  ⚠️ 尚无基线 —— 首次运行请加 --update 建立');
  else {
    console.log('  记录时间：' + st.recordedAt);
    console.log('  文档生成：' + st.generator + ' on ' + st.generatedAt);
    console.log('  站点类数：' + (st.classes || []).length + ' · 本地类数：' + localClasses().length);
    console.log('  宿主版本记录：' + JSON.stringify(st.hostVersions || {}));
  }
  console.log('\n抓取文档站…');
  const meta = await fetchDocMeta();
  console.log('  现在：' + meta.generator + ' on ' + meta.generatedAt);
  console.log('  类清单：' + meta.classes.length + ' 个');

  const local = localClasses();
  const dc = diffClasses(local, meta.classes);
  console.log('  本地独有（站点没有）：' + (dc.onlyLocal.length ? dc.onlyLocal.join(', ') : '无'));
  console.log('  站点独有（本地缺）：' + (dc.onlyRemote.length ? dc.onlyRemote.join(', ') : '无'));

  if (!st) return { needUpdate: true, reason: '无基线' };
  if (st.generatedAt !== meta.generatedAt) return { needUpdate: true, reason: '时间戳变化：' + st.generatedAt + ' → ' + meta.generatedAt };
  if (dc.onlyRemote.length) return { needUpdate: true, reason: '出现本地没有的类：' + dc.onlyRemote.join(', ') };
  return { needUpdate: false, reason: '时间戳未变（' + meta.generatedAt + '）' };
}

// ---------- HTML → Markdown ----------
const txt = (s) => s.replace(/<[^>]+>/g, '').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&amp;/g, '&').replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/\s+/g, ' ').trim();

function convertClass(name, html) {
  const start = html.indexOf('<h2>' + name + '</h2>');
  const body = start >= 0 ? html.slice(start) : html;
  const out = ['# ' + name, ''];
  // Extends
  const extIdx = body.indexOf('Extends');
  if (extIdx >= 0) {
    const seg = body.slice(extIdx, extIdx + 400);
    const m = seg.match(/<a href="([A-Za-z_][A-Za-z0-9_]*)\.html"[^>]*>([^<]+)<\/a>/);
    if (m) out.push('Extends', '', '- ' + m[2], '');
  }
  out.push('Methods', '');
  // 方法块：<h4 class="name" id="X">...
  const parts = body.split(/<h4 class="name"/).slice(1);
  for (const p of parts) {
    const idm = p.match(/id="([^"]+)"/);
    if (!idm) continue;
    const headEnd = p.indexOf('</h4>');
    const head = p.slice(0, headEnd);
    const sig = head.match(/<span class="signature">([\s\S]*?)<\/span>/);
    const sigText = sig ? txt(sig[1]) : '';
    const nameOnly = txt(head.replace(/<span class="signature">[\s\S]*$/, ''));
    out.push('### ' + nameOnly + (sigText ? ' ' + sigText : ''));
    out.push('');
    const block = p.slice(headEnd);
    const untilNext = block.split(/<h4 class="name"/)[0];
    const inh = untilNext.match(/Inherited From:[\s\S]{0,160}?<\/p>/);
    if (inh) { out.push('Inherited From: ' + txt(inh[0]).replace(/^Inherited From:\s*/, '')); out.push(''); }
    const desc = untilNext.match(/<div class="description">([\s\S]*?)<\/div>/);
    if (desc) {
      const paras = [...desc[1].matchAll(/<p>([\s\S]*?)<\/p>/g)].map((m) => txt(m[1])).filter(Boolean);
      paras.forEach((x) => { out.push(x); out.push(''); });
    }
    // 参数表
    const tbl = untilNext.match(/<table>([\s\S]*?)<\/table>/);
    if (tbl) {
      out.push('**Parameters::**', '');
      out.push('| Name | Type | Description |');
      out.push('|------|------|-------------|');
      [...tbl[1].matchAll(/<tr>([\s\S]*?)<\/tr>/g)].forEach((r) => {
        const tds = [...r[1].matchAll(/<td[^>]*>([\s\S]*?)<\/td>/g)].map((m) => txt(m[1]));
        if (tds.length >= 3) out.push('| ' + tds.slice(0, 3).join(' | ') + ' |');
      });
      out.push('');
    }
    // 返回
    const ret = untilNext.match(/<h5>Returns?::?<\/h5>([\s\S]*?)(?=<h5>|$)/);
    const dl = untilNext.match(/<dt>Type<\/dt>\s*<dd>([\s\S]*?)<\/dd>/);
    if (ret || dl) {
      out.push('**Returns::**', '');
      const rdesc = ret ? [...ret[1].matchAll(/<p>([\s\S]*?)<\/p>/g)].map((m) => txt(m[1])).filter(Boolean) : [];
      rdesc.forEach((x) => { out.push(x); out.push(''); });
      if (dl) { out.push('Type ' + txt(dl[1])); out.push(''); }
    }
  }
  return out.join('\n').replace(/\n{3,}/g, '\n\n').trim() + '\n';
}

/** 只记基线，**不重写本地 md**（用在"文档没变、但需要留档"的时候） */
async function doBaseline() {
  const meta = await fetchDocMeta();
  const prev = loadState() || {};
  let hosts = prev.hostVersions || {};
  try {
    const ipc = require(path.join(ROOT, 'server', 'dist', 'fileipc.js'));
    const parts = [];
    for (const h of ['sv', 'ix']) { const hb = ipc.readHeartbeat(h); if (hb) parts.push(h + '=' + hb.version + ' (' + hb.hostName + ')'); }
    if (parts.length) hosts = { ...hosts, [new Date().toISOString().slice(0, 10)]: parts.join(' / ') };
  } catch { /* 无桥也能记 */ }
  const dc = diffClasses(localClasses(), meta.classes);
  saveState({
    source: INDEX,
    generator: meta.generator,
    generatedAt: meta.generatedAt,
    footer: meta.footer,
    recordedAt: new Date().toISOString(),
    classes: meta.classes,
    linkedClasses: meta.linkedClasses,
    extraClasses: meta.extraClasses,
    localClasses: localClasses(),
    hostVersions: hosts,
    localDocs: '既有版本：本站 api/*.md 为**此前从同一站点 HTML 转换**而来；本工具第一次只记基线、不重写。' +
      '当 `generatedAt` 变化时再跑 --update（会先备份现有 md）。',
    note: '判据＝页脚 generatedAt；变了 ⇒ --update；宿主版本向前更新时启动自检会自动 check（--startup）',
  });
  console.log('基线已记录 → ' + STATE);
  console.log('  文档生成：' + meta.generator + ' on ' + meta.generatedAt);
  console.log('  类清单：' + meta.classes.length + ' 个（index 链接 ' + meta.linkedClasses.length + ' + 站上另存 ' + meta.extraClasses.length + '）');
  console.log('  本地类（未重写）：' + localClasses().length + ' 个');
  console.log('  本地独有（站点无）：' + (dc.onlyLocal.length ? dc.onlyLocal.join(', ') : '无'));
  console.log('  站点独有（本地缺）：' + (dc.onlyRemote.length ? dc.onlyRemote.join(', ') : '无'));
  console.log('  宿主版本：' + JSON.stringify(hosts));
}

async function doUpdate(force) {
  const res = await doCheck();
  if (!res.needUpdate && !force) { console.log('\n✅ 文档未变（' + res.reason + '），不重写本地 md。'); return; }
  console.log('\n' + (res.needUpdate ? '⚠️ ' + res.reason : '（--force）') + ' ⇒ 先备份，再抓取并重写本地 API 文档…');
  const bak = path.join(API_DIR, '_bak-' + new Date().toISOString().replace(/[:.]/g, '-').slice(0, 19));
  fs.mkdirSync(bak, { recursive: true });
  fs.readdirSync(API_DIR).filter((f) => f.endsWith('.md')).forEach((f) => fs.copyFileSync(path.join(API_DIR, f), path.join(bak, f)));
  console.log('  已备份 ' + fs.readdirSync(bak).length + ' 个 md → ' + path.relative(ROOT, bak));
  const meta = await fetchDocMeta();
  let ok = 0, fail = [], kept = [];
  for (const cls of meta.classes) {
    try {
      const html = await http(BASE + cls + '.html');
      fs.writeFileSync(path.join(API_DIR, cls + '.md'), convertClass(cls, html), 'utf8');
      ok++;
    } catch (e) {
      if (fs.existsSync(path.join(API_DIR, cls + '.md'))) kept.push(cls + '（保留本地）'); else fail.push(cls + '（' + e.message + '）');
    }
  }
  console.log('  重写 ' + ok + ' 个类文件' + (kept.length ? '，保留 ' + kept.length + '：' + kept.join(' / ') : '') + (fail.length ? '，失败 ' + fail.length + '：' + fail.join(' / ') : ''));
  const prev = loadState() || {};
  saveState({
    source: INDEX,
    generator: meta.generator,
    generatedAt: meta.generatedAt,
    footer: meta.footer,
    recordedAt: new Date().toISOString(),
    classes: meta.classes,
    linkedClasses: meta.linkedClasses,
    extraClasses: meta.extraClasses,
    localClasses: localClasses(),
    hostVersions: prev.hostVersions || {},
    lastUpdate: { at: new Date().toISOString(), written: ok, kept: kept.length, failed: fail.length, backup: path.basename(bak) },
    note: '本地 api/*.md 由 tools/api-docs-sync.cjs 从站点 HTML 生成；改前有 _bak-* 备份',
  });
  console.log('  已更新基线：' + STATE);
}

/**
 * 记录宿主版本（2026-09-21 改为**合并式**）
 *
 * 旧行为是**整条覆盖**：`--record-host auto` 只把**当时连着的**宿主拼成一条字符串。实测代价（2026-09-21）：
 *   · 只有 IX 在线时跑一次 ⇒ 记录里 sv1/sv2 **被抹掉**（SV 用户的提示从此无从比对）；
 *   · 一个宿主都没连着时 ⇒ 写入 `unknown`；而 `host-version-notice` 的判据是"记录里抠不出数字就不动作"
 *     ⇒ **提示机制被静默关掉**（不报错、也没人会发现）。
 *
 * 现行为：以**上一条记录**为底，**读得到的变体就地刷新**（附当时的宿主名），读不到的**保留旧值**；
 * 一条都读不到就**什么都不写**（沿用上一条）。变体判定走 `tools/lib-host-version.cjs`，与读侧同一份规则。
 */
async function recordHost(ver) {
  const st = loadState() || { source: INDEX, classes: [], hostVersions: {} };
  st.hostVersions = st.hostVersions || {};
  const prevRaw = Object.values(st.hostVersions).pop() || '';
  const prev = HV.parseRecord(prevRaw);
  let v = ver;
  if (ver === 'auto') {
    const now = {};
    const names = {};
    try {
      const ipc = require(path.join(ROOT, 'server', 'dist', 'fileipc.js'));
      for (const h of ['sv', 'ix']) {
        const hb = ipc.readHeartbeat(h);
        if (!hb) continue;
        const variant = HV.variantOf(h, hb);
        now[variant] = hb.version;
        names[variant] = hb.hostName;
      }
    } catch { /* 桥没起 / 心跳读不到 ⇒ 按"没读到"处理，不写 unknown */ }
    if (Object.keys(now).length) {
      const m = HV.mergeRecord(prevRaw, now, names);
      v = m.record;
      console.log('  读到：' + m.refreshed.map((k) => k + '=' + now[k]).join(' · ') +
        (m.kept.length ? ' · 沿用旧值：' + m.kept.join(' / ') : ''));
      if (!Object.keys(prev).length) console.log('  （无历史记录 ⇒ 本次即首次建立基线）');
    } else if (prevRaw) {
      console.log('  ⚠️ 没读到任何桥心跳 ⇒ 保留上一条记录（**不写 unknown**）：' + prevRaw);
      return;
    } else {
      console.log('  ⚠️ 没读到桥心跳、也没有历史记录 ⇒ 本次不写（等桥在线时再记）');
      return;
    }
  }
  st.hostVersions[new Date().toISOString().slice(0, 10)] = v;
  st.recordedHostAt = new Date().toISOString();
  saveState(st);
  console.log('已记录宿主版本：' + v + ' → ' + STATE);
}

async function doStartup() {
  const st = loadState();
  if (!st) { console.log('[api-docs] 无基线：请先跑 --update 建立（一次性）'); return; }
  // ⚠️ 2026-09-21 修正一处**长期误报**：旧实现从记录字符串里取**第一个数字**（那是 sv1 的版本，
  //    因为记录按 sv1/sv2/ix 定序）去和"当前这条心跳的版本"比 —— 若在线的是 **SV2**，就是拿
  //    `sv1=1.11.2` 与 `2.2.1` 比 ⇒ 每次都判"宿主已升级"。现按**变体**逐条比对（同一份 `lib-host-version`，
  //    与 `host-version-notice.cjs` 的口径完全一致：sv 通道靠 hostName 分 SV1/SV2）。
  const base = HV.latestHostVersions(STATE);
  const live = [];
  try {
    const ipc = require(path.join(ROOT, 'server', 'dist', 'fileipc.js'));
    for (const h of ['sv', 'ix']) {
      const hb = ipc.readHeartbeat(h);
      if (!hb) continue;
      const variant = HV.variantOf(h, hb);
      const recorded = base.parsed[variant] || null;
      live.push({ variant, now: hb.version, recorded, cmp: recorded ? HV.cmpSemver(hb.version, recorded) : null });
    }
  } catch { /* 桥没起也无所谓 */ }

  if (!live.length) {
    console.log('[api-docs] 启动自检：桥未在线（读到 0 条心跳）⇒ 不动作');
    return;
  }
  console.log('[api-docs] 启动自检（基线 ' + (base.at || '无') + '）：' +
    live.map((x) => x.variant + ' 现在 ' + x.now + ' / 基线 ' + (x.recorded || '无')).join(' · '));
  for (const x of live) {
    if (x.cmp === null) console.log('[api-docs] ' + x.variant + '：基线缺失或版本号无法比较 ⇒ 不动作');
  }
  const ahead = live.filter((x) => x.cmp === 1);
  if (!ahead.length) {
    console.log('[api-docs] 宿主版本未超过包内基线 ⇒ 不需要重新分发包');
    return;
  }
  // 2026-09-14 分发政策定案：客户端**不出网、不自动检测更新**（更新 = 用户重新装安装包）。
  // 所以这里**不再去抓文档站**，只做离线比对 + 本地提示；查站/复检由开发侧手动跑 --check。
  for (const x of ahead) {
    console.log('[api-docs] ⚠️ 宿主已升级：' + x.variant + ' 现在是 ' + x.now + '，本安装包的 API 基线是 ' + x.recorded + '。');
  }
  console.log('[api-docs]    本包的 API 文档与缺陷表可能已过期 ⇒ 建议下载最新 AKDAgent 安装包。');
  console.log('[api-docs]    （本程序不会联网检测；开发侧手动跑：node tools/api-docs-sync.cjs --check）');
  if (fs.existsSync(path.join(ROOT, 'tools', 'known-bugs.cjs'))) {
    console.log('[api-docs]    已知缺陷复检：node tools/known-bugs.cjs --check');
  }
}

(async () => {
  try {
    if (FLAG('--record-host')) return recordHost(OPT('--record-host') || 'auto');
    if (FLAG('--startup')) return doStartup();
    if (FLAG('--baseline')) return doBaseline();
    if (FLAG('--update')) return doUpdate(FLAG('--force'));
    const res = await doCheck();
    console.log('\n结论：' + (res.needUpdate ? '⚠️ 需要更新 —— ' + res.reason + '\n      跑：node tools/api-docs-sync.cjs --update' : '✅ 无需更新 —— ' + res.reason));
  } catch (e) {
    console.error('❌ ' + e.message);
    process.exit(1);
  }
})();
